export function count(e,o,t=`${o}s`){return`${e} ${e===1?o:t}`}export function welcomeLine(e){const o=e.dueToday+e.overdue;return o>0?`Welcome back. ${count(o,"follow-up")} ${o===1?"is":"are"} waiting for you today.`:e.upcoming>0?`Welcome back. The desk is clear today, and ${count(e.upcoming,"event")} ${e.upcoming===1?"is":"are"} on the calendar this week.`:e.applications>0?"Welcome back. The desk is clear today.":"Welcome back. The office is ready whenever you are."}export function pageTitle(e,o){const t=o.dueToday+o.overdue;return t>0?`(${t}) ${e}`:e}export function weekCardLines(e,o,t){const r=e.count-e.goal;let a;return r>0?a=`Weekly goal of ${e.goal} reached, plus ${r} more!`:r===0?a=`Weekly goal of ${e.goal} reached!`:a=`${-r} to go toward my goal of ${e.goal}`,{label:"CORNER OFFICE",headline:`${count(e.count,"application")} sent this week`,goal:a,met:r>=0,date:`Week of ${o}`,chart:"Applications sent each week",footer:`Track your own job search at ${t}`}}export function weekCardShareText(e,o){return`${e.headline}. ${e.goal} Track your own job search at ${o}`}export function weekCardButton(e){return e?"Share my week":"Save a picture of my week"}export function weekCardDone(e){return e==="shared"?"Thank you for sharing your week!":e==="saved"?"A picture of your week is in your downloads.":e==="failed"?"Sorry, the picture could not be made. Please try again in a moment.":""}export function storageNote(e,o){switch(e){case"unavailable":return"This browser is not letting the office save, so anything you enter will be gone when the tab closes. A private window is the usual reason.";case"newer":return"Your office was saved by a newer version of this page, so it has been left exactly as it was. Reloading the page should open it.";case"unreadable":return"The saved office could not be read, so it has been left untouched and nothing will be saved over it.";default:return o&&o.warn?"Your office is using most of the space this browser allows. Saving a backup soon would be wise.":""}}export function clockTime(e){const o=e.getHours(),t=String(e.getMinutes()).padStart(2,"0");return`${o%12===0?12:o%12}:${t} ${o<12?"AM":"PM"}`}export function dayStartLine(e){return`A day is going by at the window, starting from ${clockTime(e)}. Stop the day ends it whenever you like.`}export function dayEndLine(e,o){return o?`A whole day has gone by. It is ${clockTime(e)} again.`:`Back to the present. It is ${clockTime(e)}.`}
